  n=len(pts); return (n, round(sum(x for x,y in pts)/n,2), round(sum(y for x,y in pts)/n,2), min(x for x,y in pts), max(x for x,y in pts),min(y for x,y in pts), max(y for x,y in pts)) if n else None
